#[cfg(feature = "db")]
#[test]
fn test_job_status_invalid_uuid() {
    let output = astro_clock()
        .args(&["job", "status", "not-a-uuid"])
        .output()
        .expect("Failed to execute command");

    // Should fail with error about invalid UUID
    assert!(!output.status.success());
