#[cfg(feature = "db")]
#[tokio::test]
#[ignore = "requires TEST_PG_URL and TimescaleDB with seed data"]
async fn cli_job_status_roundtrip() {
    // Create a sync load job (completes immediately)
    let load_output = cli()
        .args(&[
            "load",
            "--start",
            "2025-02-01",
            "--days",
            "1",
            "--sync",
        ])
        .output()
        .expect("Failed to execute load");

    assert!(load_output.status.success(), "load should succeed");

    // List jobs and find the one we just created
    let list_output = cli()
        .args(&["job", "list", "--status", "complete", "--limit", "5"])
        .output()
        .expect("Failed to list jobs");

    assert!(list_output.status.success(), "job list should succeed");
    let list_stdout = String::from_utf8_lossy(&list_output.stdout);
    assert!(
        list_stdout.contains("Jobs") || list_stdout.contains("complete"),
        "should list complete jobs\nstdout: {list_stdout}"
    );

    // Extract a job ID from the list output (format: "XXXXXXXX-...")
    // The table format shows truncated IDs like "xxxxxxxx..."
    // Try to find a UUID-like pattern
    let job_id = extract_job_id_from_output(&list_stdout);

    if let Some(id) = job_id {
        let status_output = cli()
            .args(&["job", "status", &id])
            .output()
            .expect("Failed to get job status");

        let status_stdout = String::from_utf8_lossy(&status_output.stdout);
        assert!(
            status_output.status.success(),
            "job status should succeed\nstdout: {status_stdout}"
        );
        assert!(
            status_stdout.contains("complete")
                || status_stdout.contains("Complete")
                || status_stdout.contains("Status"),
            "should show job status\nstdout: {status_stdout}"
        );
    }
}

/// Extract a full UUID from the job list output.
/// The list shows truncated IDs; we look for a UUID pattern.
#[cfg(feature = "db")]
fn extract_job_id_from_output(output: &str) -> Option<String> {
    // Look for UUID pattern in the output
    let re = regex_lazy();
    for line in output.lines() {
        if let Some(id) = re.find(line) {
            return Some(id.as_str().to_string());
        }
    }
    None
}

#[cfg(feature = "db")]
fn regex_lazy() -> &'static std::sync::LazyLock<regex::Regex> {
    use std::sync::LazyLock;
    static RE: LazyLock<regex::Regex> =
        LazyLock::new(|| regex::Regex::new(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}").unwrap());
    &RE
}

